'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useEffect, useMemo, useState } from 'react';
import { BrandLogo, ProfileMenu, ThemeTools } from '@/app/ThemeTools';
import UiIcon from '@/app/UiIcon';
import AdminSettings from '@/app/super-admin/AdminSettings';
import AdminRecordModal from '@/app/super-admin/AdminRecordModal';
import TablePagination from '@/app/TablePagination';
import { downloadCsv } from '@/lib/csv';
import CsvImport from '@/app/CsvImport';

type Item = { label: string; slug: string; glyph: string };
const groups: { title: string; items: Item[] }[] = [
  { title: 'MAIN', items: [{ label: 'Dashboard', slug: 'dashboard', glyph: '—' }] },
  { title: 'ORGANIZATION', items: [
    { label: 'Hospital Settings', slug: 'settings', glyph: '?' },
    { label: 'Locations', slug: 'locations', glyph: '?' },
    { label: 'User Management', slug: 'users', glyph: '?' },
    { label: 'Roles & Permissions', slug: 'roles', glyph: '?' },
  ] },
  { title: 'PHARMACY CONFIGURATION', items: [
    { label: 'Drug Catalogue', slug: 'drugs', glyph: '?' },
    { label: 'Suppliers', slug: 'suppliers', glyph: '?' },
    { label: 'Inventory Settings', slug: 'settings/inventory', glyph: '?' },
    { label: 'Transaction Numbering', slug: 'settings/numbering', glyph: '#' },
  ] },
  { title: 'SYSTEM', items: [
    { label: 'Notifications', slug: 'notifications', glyph: '?' },
    { label: 'Audit Logs', slug: 'audit-logs', glyph: '=' },
    { label: 'Reports', slug: 'reports', glyph: '?' },
    { label: 'Backup & System Health', slug: 'system-health', glyph: '?' },
  ] },
];

const roleNames = ['Super Administrator','CMD / Authorized Executive','Head Pharmacist','DRF Store Keeper','Pharmacy Dispenser','Pharmacy Supervisor','Cashier','Procurement Officer','Internal Auditor','System Administrator'];
const pageInfo: Record<string, { title: string; subtitle: string; action?: string }> = {
  dashboard: { title: 'System Overview', subtitle: 'Monitor BKD General Hospital Pharmacy Operations' },
  users: { title: 'User Management', subtitle: 'Create accounts and manage application access.', action: 'Create User' },
  roles: { title: 'Roles & Permissions', subtitle: 'Review the roles and access controls for the pharmacy platform.' },
  locations: { title: 'Location Management', subtitle: 'Manage pharmacy and central-store locations.', action: 'Add Location' },
  settings: { title: 'Hospital Settings', subtitle: 'Configure organization-wide pharmacy settings.' },
  'settings/inventory': { title: 'Inventory Settings', subtitle: 'Set stock, expiry, and valuation policies.' },
  'settings/numbering': { title: 'Transaction Numbering', subtitle: 'Configure reference numbering for pharmacy documents.' },
  drugs: { title: 'Drug Catalogue', subtitle: 'Manage medicine records, units, and product status.', action: 'Add Drug' },
  suppliers: { title: 'Supplier Management', subtitle: 'Manage supplier records and review purchasing relationships.', action: 'Add Supplier' },
  'audit-logs': { title: 'Audit Logs', subtitle: 'Review system and pharmacy events with traceable references.' },
  'system-health': { title: 'Backup & System Health', subtitle: 'Monitor availability, backups, storage, and system events.' },
  notifications: { title: 'Notifications', subtitle: 'Review alerts and administrative tasks for your account.' },
  reports: { title: 'Administrative Reports', subtitle: 'Review permitted system and operational summaries.' },
  profile: { title: 'My Profile', subtitle: 'View your account details and security options.' },
};

function Icon({ name }: { name: string }) { return <span className="nav-icon"><UiIcon name={name} size={17}/></span>; }
function Button({ children, kind = 'secondary', onClick, disabled = false }: { children: React.ReactNode; kind?: 'primary'|'secondary'|'quiet'; onClick?: () => void; disabled?: boolean }) {
  return <button type="button" className={`button button-${kind}`} disabled={disabled} onClick={onClick}>{children}</button>;
}
function CardTitle({ title, extra }: { title: string; extra?: React.ReactNode }) { return <div className="card-heading"><h2>{title}</h2>{extra}</div>; }
function Empty({ title, note }: { title: string; note: string }) { return <div className="empty-state"><div className="empty-mark"><UiIcon name="file" size={20}/></div><strong>{title}</strong><span>{note}</span></div>; }

export default function SuperAdminPage() {
  const pathname = usePathname();
  const route = pathname.replace('/super-admin/', '').replace(/\/$/, '') || 'dashboard';
  const info = pageInfo[route] ?? pageInfo.dashboard;
  const [drawer, setDrawer] = useState(false);
  const [modal, setModal] = useState('');
  const [editingRecord,setEditingRecord]=useState<any|null>(null);
  const [notice, setNotice] = useState('');
  const [search, setSearch] = useState('');
  const [tab, setTab] = useState('General');
  const [range, setRange] = useState('Last 30 days');
  const [expanded, setExpanded] = useState<Record<string, boolean>>({ ORGANIZATION: true, 'PHARMACY CONFIGURATION': true, SYSTEM: true });
  const [statusFilter, setStatusFilter] = useState('All statuses');
  const [roleFilter, setRoleFilter] = useState('All roles');
  const [locFilter, setLocFilter] = useState('All locations');
  const [liveRows,setLiveRows]=useState<any[]>([]);const [locationRows,setLocationRows]=useState<any[]>([]);const [roleRows,setRoleRows]=useState<any[]>([]);const [dataError,setDataError]=useState('');const [dataLoading,setDataLoading]=useState(false);const [refreshKey,setRefreshKey]=useState(0);
  const [accountName,setAccountName]=useState('Administrator');
  const resource=route==='dashboard'?'dashboard':route==='users'?'users':route==='roles'?'roles':route==='locations'?'locations':route==='settings/numbering'?'numbering':route==='settings'||route==='settings/inventory'?'settings':route==='drugs'?'drugs':route==='suppliers'?'suppliers':route==='audit-logs'?'audit':route==='system-health'?'health':route==='reports'?'audit':route==='notifications'?'notifications':null;
  useEffect(()=>{if(!resource){setLiveRows([]);return}let active=true;setDataLoading(true);setDataError('');fetch(`/api/admin?resource=${resource}`).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error||'Unable to load records');return d.data}).then(d=>{if(active)setLiveRows(Array.isArray(d)?d:d?[d]:[])}).catch(e=>{if(active){setLiveRows([]);setDataError(e.message)}}).finally(()=>{if(active)setDataLoading(false)});return()=>{active=false}},[resource,refreshKey]);
  useEffect(()=>{fetch('/api/auth/me').then(r=>r.json()).then(d=>{if(d.user?.name)setAccountName(d.user.name)}).catch(()=>{})},[]);
  useEffect(()=>{let active=true;fetch('/api/admin?resource=locations').then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load locations');return d.data}).then(rows=>{if(active)setLocationRows(Array.isArray(rows)?rows:[])}).catch(()=>{if(active)setLocationRows([])});return()=>{active=false}},[refreshKey]);
  useEffect(()=>{let active=true;fetch('/api/admin?resource=roles').then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load roles');return d.data}).then(rows=>{if(active)setRoleRows(Array.isArray(rows)?rows:[]) }).catch(()=>{if(active)setRoleRows([])});return()=>{active=false}},[refreshKey]);
  const matchingLocations = useMemo(() => liveRows.filter((x) => `${x.name} ${x.code} ${x.type}`.toLowerCase().includes(search.toLowerCase())), [liveRows,search]);
  const notify = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 3600); };
  const closeModal = () => setModal('');

  return <div className="app-shell">
    {drawer && <button className="scrim" aria-label="Close navigation" onClick={() => setDrawer(false)} />}
    <aside className={`sidebar ${drawer ? 'sidebar-open' : ''}`}>
      <div className="brand">
        <BrandLogo />
        <button className="mobile-close" onClick={() => setDrawer(false)} aria-label="Close menu">—</button>
      </div>
      <div className="workspace-label">ADMIN WORKSPACE</div>
      <nav className="side-nav" aria-label="Administration navigation">
        {groups.map((group) => <div className="nav-group" key={group.title}>
          {group.title === 'MAIN' ? null : <button className="nav-group-title" onClick={() => setExpanded((e) => ({ ...e, [group.title]: !e[group.title] }))}>{group.title}<span>{expanded[group.title] ? '-' : '+'}</span></button>}
          {(group.title === 'MAIN' || expanded[group.title]) && group.items.map((item) => {
            const active = route === item.slug || (item.slug === 'settings' && route.startsWith('settings/'));
            return <Link key={item.slug} onClick={() => setDrawer(false)} href={`/super-admin/${item.slug}`} className={`nav-link ${active ? 'nav-link-active' : ''}`}><Icon name={item.slug}/><span>{item.label}</span>{item.slug === 'system-health' && <i className="nav-dot" />}</Link>;
          })}
        </div>)}
      </nav>
      <div className="sidebar-bottom">
        <Link href="/profile" className={`nav-link ${route === 'profile' ? 'nav-link-active' : ''}`}><Icon name="user"/><span>My Profile</span></Link>
        <button className="nav-link logout" onClick={async () => { await fetch('/api/auth/logout',{method:'POST'}); location.assign('/login'); }}><Icon name="logout"/><span>Sign Out</span></button>
        <div className="sidebar-user"><div className="avatar avatar-small">SA</div><div><strong>Super Administrator</strong><small>System administrator</small></div><span className="online-dot" /></div>
      </div>
    </aside>

    <div className="main-shell">
      <header className="topbar">
        <button className="menu-button" onClick={() => setDrawer(true)} aria-label="Open navigation"><UiIcon name="menu"/></button>
        <div className="crumb"><span>Administration</span><b>/</b><strong>{info.title}</strong></div>
        <div className="topbar-actions">
          <button className="icon-button" title="Search" aria-label="Search this page" onClick={() => document.getElementById('page-search')?.focus()}><UiIcon name="search"/></button>
          <button className="icon-button notification-button" title="Notifications" aria-label="Notifications" onClick={() => location.assign('/super-admin/notifications')}><UiIcon name="bell"/><i /></button>
          <div className="top-divider" />
          <ThemeTools />
          <ProfileMenu name={accountName} role="Super Administrator" />
        </div>
      </header>

      <main className="content">
        <div className="page-header">
          <div><div className="eyebrow">BKD GENERAL HOSPITAL <span>—</span> ADMINISTRATION</div><h1>{info.title}</h1><p>{info.subtitle}</p></div>
          <div className="header-controls">{route === 'dashboard' && <><label className="select-wrap"><span className="sr-only">Date range</span><select value={range} onChange={(e) => setRange(e.target.value)}><option>Today</option><option>Last 7 days</option><option>Last 30 days</option><option>Custom range</option></select></label><Button onClick={() => setRefreshKey(x=>x+1)}><UiIcon name="refresh" size={15}/> <span>Refresh</span></Button><Button kind="primary" disabled={!liveRows.length} onClick={()=>downloadCsv('pharmacy-dashboard-summary.csv',liveRows)}><UiIcon name="download" size={15}/> <span>Export summary</span></Button></>}{info.action && <Button kind="primary" onClick={() => {setEditingRecord(null);setModal(route === 'users' ? 'Create user' : route === 'locations' ? 'Add location' : route === 'drugs' ? 'Add drug' : 'Add supplier')}}>+ {info.action}</Button>}</div>
        </div>

        {route === 'dashboard' && <Dashboard range={range} notify={notify} data={liveRows[0]} locations={locationRows} error={dataError} loading={dataLoading} />}
        {route === 'users' && <Users rows={liveRows} roles={roleRows} error={dataError} loading={dataLoading} search={search} setSearch={setSearch} statusFilter={statusFilter} setStatusFilter={setStatusFilter} roleFilter={roleFilter} setRoleFilter={setRoleFilter} locFilter={locFilter} setLocFilter={setLocFilter} onCreate={() => {setEditingRecord(null);setModal('Create user')}} onEdit={(row)=>{setEditingRecord(row);setModal('Edit user')}} onSuspend={async(row)=>{const status=row.status==='suspended'?'active':'suspended';const r=await fetch('/api/admin',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({resource:'users',id:row.id,status})});const d=await r.json();if(!r.ok)notify(d.error||'Could not update user');else{notify(`Account ${status}. Active sessions were revoked if suspended.`);setRefreshKey(x=>x+1)}}} />}
        {route === 'roles' && <Roles rows={liveRows} error={dataError} />}
        {route === 'locations' && <Locations rows={matchingLocations} search={search} setSearch={setSearch} loading={dataLoading} error={dataError} onEdit={(row)=>{setEditingRecord(row);setModal('Edit location')}} />}
        {route === 'settings' && <AdminSettings initialTab={tab} notify={notify} rows={liveRows} onSaved={()=>setRefreshKey(x=>x+1)} />}
        {route === 'settings/inventory' && <AdminSettings initialTab="Inventory" notify={notify} rows={liveRows} onSaved={()=>setRefreshKey(x=>x+1)} />}
        {route === 'settings/numbering' && <Numbering rows={liveRows} notify={notify} onSaved={()=>setRefreshKey(x=>x+1)} />}
        {route === 'drugs' && <Drugs rows={liveRows} error={dataError} loading={dataLoading} search={search} setSearch={setSearch} notify={notify} onImported={()=>setRefreshKey(x=>x+1)} onEdit={(row)=>{setEditingRecord(row);setModal('Edit drug')}} />}
        {route === 'suppliers' && <Suppliers rows={liveRows} error={dataError} loading={dataLoading} search={search} setSearch={setSearch} notify={notify} onImported={()=>setRefreshKey(x=>x+1)} onEdit={(row)=>{setEditingRecord(row);setModal('Edit supplier')}} />}
        {route === 'audit-logs' && <AuditLogs rows={liveRows} error={dataError} loading={dataLoading} search={search} setSearch={setSearch} />}
        {route === 'system-health' && <SystemHealth rows={liveRows} error={dataError} loading={dataLoading} />}
        {route === 'notifications' && <Notifications rows={liveRows} error={dataError} onRead={async(id)=>{const r=await fetch('/api/admin',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({resource:'notifications',id})});const d=await r.json();if(!r.ok)notify(d.error||'Unable to update notification');else setRefreshKey(x=>x+1)}} />}
        {route === 'reports' && <Reports notify={notify} />}
        {route === 'profile' && <Profile />}
        <footer className="page-footer"><span>BKD General Hospital Pharmacy Management System</span><span>Powered by Kowgururu Technology Limited</span></footer>
      </main>
    </div>

    {modal && <AdminRecordModal title={modal} record={editingRecord} close={closeModal} notify={notify} onSaved={()=>setRefreshKey(x=>x+1)} locationRows={locationRows} roleRows={roleRows} />}
    {notice && <div className="toast" role="status"><span><UiIcon name="bell" size={16}/></span>{notice}<button onClick={() => setNotice('')} aria-label="Dismiss notification"><UiIcon name="close" size={15}/></button></div>}
  </div>;
}

function Dashboard({ range, notify,data,locations,error,loading }: { range: string; notify: (s: string) => void;data:any;locations:any[];error:string;loading:boolean }) {
  const kpis = [
    { title: 'Total locations', field:'total_locations', metric: data?.total_locations??0, helper: 'Configured pharmacy locations', icon: 'location', tone: 'teal' },
    { title: 'Active users', field:'active_users', metric: data?.active_users??0, helper: 'Active registered accounts', icon: 'users', tone: 'blue' },
    { title: 'Pending approvals', field:'pending_approvals', metric: data?.pending_approvals??0, helper: 'Awaiting authorized review', icon: 'shield', tone: 'amber' },
    { title: 'System alerts', field:'system_alerts', metric: data?.system_alerts??0, helper: 'Open system health events', icon: 'bell', tone: 'red' },
  ];
  return <>
    <div className="connection-note"><span className="connection-icon">i</span><div><strong>{error?'Unable to connect to the hospital database.':loading?'Loading live dashboard data.':'Dashboard metrics are connected to hospitalguru.'}</strong><span>{error||'Cards show live counts. Detailed activity charts require events in the corresponding database tables.'}</span></div><span className="api-badge"><i className={error?'offline':''}/>{loading?'Loading':error?'Unavailable':'Database'}</span></div>
    <div className="kpi-grid">{kpis.filter(k=>loading||Object.prototype.hasOwnProperty.call(data||{},k.field)).map((k) => <article className="kpi-card" key={k.title}><div className="kpi-top"><span>{k.title}</span><i className={`metric-icon ${k.tone}`}><UiIcon name={k.icon} size={17}/></i></div><strong className="metric-value">{error?'—':loading?'Loading—':k.metric}</strong><div className="metric-caption">{k.helper}</div></article>)}</div>
    <div className="dashboard-grid chart-grid">
      <section className="panel chart-panel"><CardTitle title="Inventory distribution" extra={<button className="text-button" onClick={() => location.assign('/super-admin/locations')}>Locations <UiIcon name="location" size={14}/></button>} /><div className="chart-empty"><div className="donut-placeholder"><div><UiIcon name="inventory" size={22}/><small>Stock value</small></div></div><div className="legend-list">{locations.map((l, i) => <div key={l.code}><span className={`legend-dot dot-${i}`} />{l.name}<b>—</b></div>)}</div></div><div className="panel-footnote">Stock value will appear when authorized inventory balances are available.</div></section>
      <section className="panel chart-panel"><CardTitle title="System activity" extra={<select className="mini-select" value={range} onChange={() => {}} aria-label="Selected date range"><option>{range}</option></select>} /><div className="line-empty"><div className="chart-gridlines"><span /><span /><span /><span /></div><div className="chart-empty-message"><span className="chart-symbol"><UiIcon name="chart" size={20}/></span><strong>No activity data yet</strong><small>Usage and transaction events appear here when activity records are available.</small></div><div className="chart-axis"><span>Start</span><span>Activity over time</span><span>Now</span></div></div><div className="chart-legend"><span><i className="legend-blue" />User activity</span><span><i className="legend-teal" />Transactions created</span><span><i className="legend-orange" />Failed operations</span></div></section>
    </div>
    <section className="panel activity-panel"><CardTitle title="Recent activity" extra={<button className="text-button" onClick={() => location.assign('/super-admin/audit-logs')}>View audit log <UiIcon name="file" size={14}/></button>} /><div className="table-wrap"><table><thead><tr><th>S/N</th><th>TIMESTAMP</th><th>USER</th><th>ACTION</th><th>MODULE</th><th>REFERENCE</th><th>STATUS</th></tr></thead><tbody><tr><td colSpan={7}><Empty title="No recorded activity" note="Activity will appear here after the audit event feed is connected." /></td></tr></tbody></table></div></section>
    <div className="dashboard-grid alert-grid"><section className="panel"><CardTitle title="System alerts" extra={<span className="soft-pill">Technical</span>} /><Empty title="No system alerts loaded" note="Backup and system health events will appear here." /></section><section className="panel"><CardTitle title="Administrative tasks" extra={<span className="soft-pill soft-amber">Workflow</span>} /><Empty title="No tasks loaded" note="Administrative queues are separate from pharmacy approval queues." /></section></div>
  </>;
}

function Users(props: { rows:any[];roles:any[];error:string;loading:boolean; search: string; setSearch: (v: string) => void; statusFilter: string; setStatusFilter: (v: string) => void; roleFilter: string; setRoleFilter: (v: string) => void; locFilter: string; setLocFilter: (v: string) => void; onCreate: () => void; onEdit:(row:any)=>void; onSuspend:(row:any)=>void }) {
  const [page,setPage]=useState(1);const [pageSize,setPageSize]=useState(5);
  const matching=props.rows.filter(r=>`${r.name} ${r.username} ${r.email||''}`.toLowerCase().includes(props.search.toLowerCase())&&(props.roleFilter==='All roles'||r.role_name===props.roleFilter)&&(props.locFilter==='All locations'||String(r.assigned_locations||r.location_name||'').split(', ').includes(props.locFilter))&&(props.statusFilter==='All statuses'||String(r.status).toLowerCase()===props.statusFilter.toLowerCase()));
  const pageRows=matching.slice((page-1)*pageSize,page*pageSize);
  useEffect(()=>setPage(1),[props.search,props.roleFilter,props.locFilter,props.statusFilter]);useEffect(()=>setPage(p=>Math.min(p,Math.max(1,Math.ceil(matching.length/pageSize)))),[matching.length,pageSize]);
  const cards = [['Total users',String(props.rows.length),'Registered accounts'],['Active users',String(props.rows.filter(r=>r.status==='active').length),'Accounts able to sign in'],['Suspended users',String(props.rows.filter(r=>r.status==='suspended').length),'Access temporarily disabled'],['Needs attention',String(props.rows.filter(r=>r.status==='pending').length),'Pending or flagged accounts']];
  return <><div className="summary-grid">{cards.map(([a,b,c])=><div className="summary-card" key={a}><span>{a}</span><b>{props.loading?'—':b}</b><small>{c}</small></div>)}</div><section className="panel table-panel"><div className="filter-bar"><div className="search-field"><span><UiIcon name="search" size={16}/></span><input id="page-search" placeholder="Search name, username or email" value={props.search} onChange={e=>props.setSearch(e.target.value)} /></div><select value={props.roleFilter} onChange={e=>props.setRoleFilter(e.target.value)}><option>All roles</option>{props.roles.filter(r=>r.is_active).map(r=><option key={r.id}>{r.name}</option>)}</select><select value={props.locFilter} onChange={e=>props.setLocFilter(e.target.value)}><option>All locations</option>{props.rows.flatMap(r=>String(r.assigned_locations||r.location_name||'').split(', ')).filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).map((r:string)=><option key={r}>{r}</option>)}</select><button className="button button-secondary" disabled={!matching.length} onClick={()=>downloadCsv('users.csv',matching)}>Export CSV</button><select value={props.statusFilter} onChange={e=>props.setStatusFilter(e.target.value)}><option>All statuses</option><option>Active</option><option>Suspended</option><option>Pending</option></select><button className="clear-button" onClick={()=>{props.setSearch('');props.setRoleFilter('All roles');props.setLocFilter('All locations');props.setStatusFilter('All statuses');setPage(1)}}>Clear</button></div>{props.error&&<div className="inline-error">{props.error}</div>}<div className="table-wrap"><table><thead><tr><th>S/N</th><th>USER</th><th>USERNAME</th><th>ROLE</th><th>LOCATION</th><th>STATUS</th><th>LAST LOGIN</th><th>ACTIONS</th></tr></thead><tbody>{matching.length?pageRows.map((r,i)=><tr key={r.id}><td>{(page-1)*pageSize+i+1}</td><td><div className="user-cell"><span className="avatar avatar-small">{r.name.split(/\s+/).map((v:string)=>v[0]).slice(0,2).join('').toUpperCase()}</span><span><b>{r.name}</b><small>{r.email||r.staff_id||'—'}</small></span></div></td><td>{r.username}</td><td>{r.role_name}</td><td>{r.assigned_locations||r.location_name||'—'}</td><td><span className={`status-pill ${r.status==='active'?'status-active':r.status==='pending'?'soft-amber':'status-inactive'}`}>{r.status}</span></td><td>{r.last_login_at?new Date(r.last_login_at).toLocaleString():'Never'}</td><td><button className="row-action" onClick={()=>props.onEdit(r)}>Edit</button><button className="row-action" onClick={()=>props.onSuspend(r)}>{r.status==='suspended'?'Reactivate':'Suspend'}</button></td></tr>):<tr><td colSpan={8}><Empty title={props.loading?'Loading users':props.error?'Could not load users':'No user records match'} note={props.error||'Create an account to populate this list. Search and filters apply to database records.'}/></td></tr>}</tbody></table></div><TablePagination total={matching.length} page={page} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={setPageSize}/></section><div className="inline-help"><b>Account integrity</b><span>Suspending a user revokes active sessions. Historical transactions remain attached to the original account.</span><button onClick={props.onCreate}>Create account <span><UiIcon name="file" size={14}/></span></button></div></>;
}

function Roles({rows,error}:{rows:any[];error:string}) {
  const [selected,setSelected]=useState('');const [permissionRows,setPermissionRows]=useState<any[]>([]);const [draft,setDraft]=useState<Record<string,boolean>>({});const [loading,setLoading]=useState(false);const [saving,setSaving]=useState(false);const [message,setMessage]=useState('');const [page,setPage]=useState(1);const [pageSize,setPageSize]=useState(5);
  const selectedRole=rows.find(role=>role.role_key===selected);
  useEffect(()=>{if(rows.length&&!rows.some(role=>role.role_key===selected))setSelected(rows[0].role_key)},[rows,selected]);
  useEffect(()=>{if(!selectedRole){setPermissionRows([]);return}let active=true;setLoading(true);setMessage('');fetch(`/api/admin?resource=role_permissions&role_id=${selectedRole.id}`).then(async response=>{const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not load role permissions.');return result.data}).then(data=>{if(!active)return;const entries=Array.isArray(data)?data:[];setPermissionRows(entries);setDraft(Object.fromEntries(entries.map((permission:any)=>[permission.permission_key,Boolean(Number(permission.granted))])))}).catch(error=>{if(active)setMessage(error instanceof Error?error.message:'Could not load role permissions.')}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[selectedRole?.id]);useEffect(()=>setPage(1),[selected]);
  const modules=[...new Set(permissionRows.map(permission=>permission.module))];const pageModules=modules.slice((page-1)*pageSize,page*pageSize);const actions=['view','create','edit','approve','delete'];
  async function save(){if(!selectedRole)return;setSaving(true);setMessage('');try{const response=await fetch('/api/admin',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({resource:'role_permissions',role_id:selectedRole.id,permissions:permissionRows.map(permission=>({permission_key:permission.permission_key,granted:Boolean(draft[permission.permission_key])}))})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Permissions could not be saved.');setMessage(`${result.updated} permissions saved to the database and audit log.`)}catch(error){setMessage(error instanceof Error?error.message:'Permissions could not be saved.')}finally{setSaving(false)}}
  return <><div className="connection-note"><span className="connection-icon">i</span><div><strong>{error||'Permission changes are saved to the database and enforced by the API.'}</strong><span>Grant only the actions required for each role. Sensitive operations remain subject to their workflow approvals.</span></div></div><div className="role-layout"><section className="panel role-list"><CardTitle title="System roles" extra={<span className="count-pill">{rows.length}</span>} />{rows.map(role=><button onClick={()=>setSelected(role.role_key)} className={`role-choice ${selected===role.role_key?'role-selected':''}`} key={role.id}><span className="role-avatar">{role.name.split(' ').map((part:string)=>part[0]).slice(0,2).join('')}</span><span><b>{role.name}</b><small>{role.user_count} users</small></span><span className="chevron">—</span></button>)}{!rows.length&&<Empty title="No roles available" note={error||'Role records could not be loaded from the database.'}/>}</section><section className="panel permissions-panel"><CardTitle title={selectedRole?.name||'Select a role'} extra={<span className="soft-pill">{selectedRole?.is_system?'System role':'Custom role'}</span>} /><p className="muted-copy">Checked actions are granted to this role. Updates are audited and take effect on the next request.</p>{message&&<div className={message.includes('saved')?'connection-note':'inline-error'}>{message}</div>}<div className="table-wrap"><table className="permission-table"><thead><tr><th>S/N</th><th>MODULE</th>{actions.map(action=><th key={action}>{action.toUpperCase()}</th>)}</tr></thead><tbody>{pageModules.map((module,index)=><tr key={module}><td>{(page-1)*pageSize+index+1}</td><td><strong>{permissionModuleLabel(module)}</strong></td>{actions.map(action=>{const key=`${module}.${action}`;const permission=permissionRows.find(item=>item.permission_key===key);return <td key={action}><input type="checkbox" aria-label={`${permissionModuleLabel(module)} ${action}`} checked={Boolean(draft[key])} disabled={!permission||loading||saving} onChange={event=>setDraft(current=>({...current,[key]:event.target.checked}))}/></td>})}</tr>)}{!modules.length&&<tr><td colSpan={7}><Empty title={loading?'Loading permissions':'No permissions found'} note={message||'Permission definitions are being prepared in the database.'}/></td></tr>}</tbody></table></div><TablePagination total={modules.length} page={page} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={setPageSize}/><div className="panel-actions"><span className="muted-copy">{loading?'Loading grants—':'Changes are recorded in the audit log.'}</span><Button kind="primary" disabled={!selectedRole||loading||saving||!permissionRows.length} onClick={save}>{saving?'Saving—':'Save permissions'}</Button></div></section></div></>;
}
function permissionModuleLabel(module:string){return module.replaceAll('_',' ').replace(/\b\w/g,letter=>letter.toUpperCase())}
function Locations({ rows, search, setSearch, loading,error,onEdit }: { rows:any[]; search: string; setSearch: (s:string)=>void;loading:boolean;error:string; onEdit: (row:any)=>void }) { return <><div className="location-toolbar"><div className="search-field"><span><UiIcon name="search" size={16}/></span><input id="page-search" placeholder="Search locations" value={search} onChange={e=>setSearch(e.target.value)} /></div><span className="result-count">{rows.length} locations</span><button className="button button-secondary" disabled={!rows.length} onClick={()=>downloadCsv('locations.csv',rows)}>Export CSV</button></div>{error&&<div className="inline-error">{error}</div>}<div className="location-grid">{rows.map((l,i)=><article className="location-card" key={l.code}><div className="location-card-top"><div className={`location-icon loc-${i%4}`}><UiIcon name="location" size={20}/></div><span className={`status-pill ${l.is_active?'status-active':'status-inactive'}`}><i />{l.is_active?'Active':'Inactive'}</span></div><h2>{l.name}</h2><div className="location-code">{l.code}</div><span className="type-label">{l.type?.replace('_',' ')}</span><div className="location-stats"><div><span>Assigned users</span><b>{l.user_count??0}</b></div><div><span>Last activity</span><b>{l.last_activity?new Date(l.last_activity).toLocaleDateString():'—'}</b></div></div><div className="location-actions"><button onClick={()=>onEdit(l)}>View details</button><button onClick={()=>onEdit(l)}>Edit location <span><UiIcon name="file" size={14}/></span></button></div></article>)}{!rows.length&&<div className="panel"><Empty title={loading?'Loading locations':error?'Unable to load locations':'No locations configured'} note={error||'The initial database schema seeds four locations. Add a location to extend the network.'}/></div>}</div><div className="inline-help"><b>Location history</b><span>Locations with historical transactions must be deactivated rather than deleted.</span><button onClick={()=>location.assign('/super-admin/settings/inventory')}>Reorder settings <span><UiIcon name="file" size={14}/></span></button></div></>; }

function Settings({ tab, setTab, notify,rows,error }: {tab:string;setTab:(s:string)=>void;notify:(s:string)=>void;rows:any[];error:string}) { const tabs=['General','Inventory','Sales','Security','Documents']; const values=Object.fromEntries(rows.map(r=>[r.setting_key,r.setting_value])); const configs:Record<string,string>={hospital_name:'BKD General Hospital',timezone:'Africa/Lagos',currency:'NGN',low_stock_threshold:'20',expiry_warning_days:'30'}; return <><section className="panel settings-panel"><div className="settings-tabs" role="tablist">{tabs.map(t=><button role="tab" aria-selected={tab===t} className={tab===t?'settings-tab active':'settings-tab'} onClick={()=>setTab(t)} key={t}>{t}</button>)}</div><div className="settings-content"><div className="settings-intro"><div><h2>{tab} configuration</h2><p>Changes to important settings should be logged and may require additional authorization.</p></div><span className="soft-pill">Hospital-wide</span></div>{tab==='General'&&<div className="form-grid"><Field label="Hospital name" value={values.hospital_name||configs.hospital_name} /><Field label="Contact email" placeholder="Enter hospital contact email" /><Field label="Phone number" placeholder="Enter contact number" /><Field label="Address" placeholder="Hospital address" /><Field label="Time zone" value={values.timezone||configs.timezone} /><Field label="Default language" value="English" /></div>}{tab==='Inventory'&&<div className="form-grid"><Field label="Expiry warning period" value={`${values.expiry_warning_days||configs.expiry_warning_days} days`} /><Field label="Default low-stock threshold" value={`${values.low_stock_threshold||configs.low_stock_threshold} units`} /><Field label="Negative stock policy" value="Prevent sale below zero" /><Field label="Valuation method" value="FIFO / earliest expiry for dispensing" /><div className="field full"><label>Unit conversions</label><p className="field-helper">Conversions are maintained per medicine in the drug catalogue.</p></div></div>}{tab==='Sales'&&<div className="form-grid"><Field label="Currency" value={`${values.currency||configs.currency} — Nigerian Naira`} /><Field label="Payment methods" value="Cash — Bank Transfer — POS Terminal" /><Field label="Receipt format" value="80 mm thermal receipt" /><Field label="Discount approval" value="Approval policy required" /><div className="field full"><label>Tax configuration</label><p className="field-helper">No tax policy is configured. Confirm applicable settings before enabling tax collection.</p></div></div>}{tab==='Security'&&<div className="form-grid"><Field label="Session timeout" placeholder="Policy not configured" /><Field label="Password policy" value="Minimum 10 characters" /><Field label="Multi-factor authentication" value="Policy not configured" /><Field label="Login rate limits" placeholder="Policy not configured" /></div>}{tab==='Documents'&&<div className="form-grid">{['GRN','Transfer','Return','Invoice','Receipt'].map(x=><Field label={`${x} number prefix`} value={`${x.toUpperCase()}-`} key={x} />)}</div>}<div className="settings-footer"><span>{error||'Read-only until the settings update service is connected.'}</span><Button kind="primary" onClick={()=>saveSettings(tab,notify)}>Save changes</Button></div></div></section></>; }

function InventorySettings({notify,rows}:{notify:(s:string)=>void;rows:any[]}) { const values=Object.fromEntries(rows.map(r=>[r.setting_key,r.setting_value]));return <><section className="panel settings-panel"><CardTitle title="Inventory policy" extra={<span className="soft-pill">Current database values</span>} /><p className="muted-copy">Set rules that control usable stock calculations, reorder alerts, expiry handling, and valuation.</p><div className="form-grid"><Field label="Low-stock default" value={`${values.low_stock_threshold||'20'} units`} /><Field label="Expiry warning period" value={`${values.expiry_warning_days||'30'} days`} /><Field label="Negative-stock policy" value="Prevent sale below zero" /><Field label="Valuation method" value="FIFO / earliest expiry for dispensing" /><Field label="Reserved stock handling" value="Exclude from available stock" /><Field label="In-transit stock handling" value="Exclude until receipt confirmation" /></div><div className="settings-footer"><span>Inventory policy updates require server-side validation and audit logging.</span><Button kind="primary" onClick={()=>saveInventorySettings(notify)}>Save settings</Button></div></section></>; }

function Numbering({notify,rows,onSaved}:{notify:(s:string)=>void;rows:any[];onSaved:()=>void}) { const refs:[string,string,string][]=[['Goods Received Note','goods_receipt','GRN-'],['Stock Transfer','stock_transfer','TRF-'],['Stock Return','stock_return','RET-'],['Invoice','invoice','INV-'],['Receipt','receipt','RCP-'],['Purchase Order','purchase_order','PO-']];const save=async()=>{const values=refs.map(([,key])=>{const row=document.querySelector(`[data-sequence="${key}"]`);const inputs=row?.querySelectorAll('input');return{sequence_key:key,prefix:inputs?.[0]?.value||'',next_number:Number(inputs?.[1]?.value||1),padding:6}});try{const r=await fetch('/api/admin',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({resource:'numbering',sequences:values})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Numbering could not be saved.');notify('Transaction numbering saved and audited.');onSaved()}catch(e){notify(e instanceof Error?e.message:'Numbering could not be saved.')}};return <section className="panel settings-panel"><CardTitle title="Reference formats" extra={<span className="soft-pill">Sequential references</span>} /><p className="muted-copy">Sequence allocation must be atomic to avoid duplicate transaction references.</p><div className="numbering-list">{refs.map(([name,key,defaultPrefix])=>{const rec=rows.find(r=>r.sequence_key===key);const prefix=rec?.prefix||defaultPrefix;const next=String(rec?.next_number||1).padStart(Number(rec?.padding||6),'0');return <div className="numbering-row" data-sequence={key} key={key}><div><b>{name}</b><small>Next reference preview</small></div><div className="prefix-input"><input aria-label={`${name} prefix`} defaultValue={prefix} /><span>-</span><input aria-label={`${name} next number`} defaultValue={next} /></div><span className="reference-preview">{prefix}{next}</span></div>})}</div><div className="settings-footer"><span>Sequence formats are saved to the hospitalguru database and audited.</span><Button kind="primary" onClick={save}>Save numbering</Button></div></section>; }

function Drugs({rows,error,loading,search,setSearch,onEdit,notify,onImported}:{rows:any[];error:string;loading:boolean;search:string;setSearch:(s:string)=>void;onEdit:(row:any)=>void;notify:(s:string)=>void;onImported:()=>void}) { const [category,setCategory]=useState('All categories');const [statusFilter,setStatusFilter]=useState('All statuses');const [page,setPage]=useState(1);const [pageSize,setPageSize]=useState(5);const results=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase())&&(category==='All categories'||r.category===category)&&(statusFilter==='All statuses'||(statusFilter==='Active'?Boolean(r.is_active):!r.is_active)));const pageRows=results.slice((page-1)*pageSize,page*pageSize);useEffect(()=>setPage(1),[search,category,statusFilter]);return <><div className="catalog-summary"><div className="search-field"><span><UiIcon name="search" size={16}/></span><input id="page-search" placeholder="Search name, SKU or barcode" value={search} onChange={e=>setSearch(e.target.value)} /></div><select value={category} onChange={e=>setCategory(e.target.value)}><option>All categories</option>{rows.map(r=>r.category).filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).map((x:string)=><option key={x}>{x}</option>)}</select><select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option>All statuses</option><option>Active</option><option>Inactive</option></select><CsvImport resource="drugs" onComplete={onImported} onMessage={notify}/><Button disabled={!results.length} onClick={()=>downloadCsv('drug-catalogue.csv',results)}>Export CSV</Button></div>{error&&<div className="inline-error">{error}</div>}<section className="panel table-panel"><div className="table-wrap"><table><thead><tr><th>S/N</th><th>DRUG CODE</th><th>GENERIC NAME</th><th>BRAND</th><th>STRENGTH / FORM</th><th>BASE UNIT</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>{pageRows.map((r,i)=><tr key={r.id}><td>{(page-1)*pageSize+i+1}</td><td>{r.sku}</td><td>{r.generic_name}</td><td>{r.brand_name||'—'}</td><td>{[r.strength,r.dosage_form].filter(Boolean).join(' / ')||'—'}</td><td>{r.base_unit}</td><td><span className={`status-pill ${r.is_active?'status-active':'status-inactive'}`}>{r.is_active?'Active':'Inactive'}</span></td><td><button className="row-action" onClick={()=>onEdit(r)}>Edit</button></td></tr>)}{!results.length&&<tr><td colSpan={8}><Empty title={loading?'Loading catalogue':error?'Catalogue unavailable':'No medicines found'} note={error||'Add a medicine to populate the catalogue.'}/></td></tr>}</tbody></table></div><TablePagination total={results.length} page={page} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={setPageSize}/></section><div className="inline-help"><b>Historical records</b><span>Medicine records used by transactions should be deactivated, never destructively deleted.</span><button>Catalogue fields <span><UiIcon name="file" size={14}/></span></button></div></>; }

function Suppliers({rows,error,loading,search,setSearch,onEdit,notify,onImported}:{rows:any[];error:string;loading:boolean;search:string;setSearch:(s:string)=>void;onEdit:(row:any)=>void;notify:(s:string)=>void;onImported:()=>void}) { const [statusFilter,setStatusFilter]=useState('All statuses');const [page,setPage]=useState(1);const [pageSize,setPageSize]=useState(5);const results=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase())&&(statusFilter==='All statuses'||(statusFilter==='Active'?Boolean(r.is_active):!r.is_active)));const pageRows=results.slice((page-1)*pageSize,page*pageSize);useEffect(()=>setPage(1),[search,statusFilter]);return <><div className="catalog-summary"><div className="search-field"><span><UiIcon name="search" size={16}/></span><input id="page-search" placeholder="Search supplier name or contact" value={search} onChange={e=>setSearch(e.target.value)} /></div><select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option>All statuses</option><option>Active</option><option>Inactive</option></select><CsvImport resource="suppliers" onComplete={onImported} onMessage={notify}/><Button disabled={!results.length} onClick={()=>downloadCsv('suppliers.csv',results)}>Export CSV</Button></div>{error&&<div className="inline-error">{error}</div>}<section className="panel table-panel"><div className="table-wrap"><table><thead><tr><th>S/N</th><th>SUPPLIER</th><th>CONTACT PERSON</th><th>PHONE / EMAIL</th><th>REGISTRATION</th><th>STATUS</th><th>LINKED GRNS</th><th>ACTIONS</th></tr></thead><tbody>{pageRows.map((r,i)=><tr key={r.id}><td>{(page-1)*pageSize+i+1}</td><td><strong>{r.name}</strong></td><td>{r.contact_person||'—'}</td><td>{r.phone||r.email||'—'}</td><td>{r.registration_no||'—'}</td><td><span className={`status-pill ${r.is_active?'status-active':'status-inactive'}`}>{r.is_active?'Active':'Inactive'}</span></td><td>{r.grn_count}</td><td><button className="row-action" onClick={()=>onEdit(r)}>Edit</button></td></tr>)}{!results.length&&<tr><td colSpan={8}><Empty title={loading?'Loading suppliers':error?'Suppliers unavailable':'No suppliers found'} note={error||'Add a supplier to populate the supplier register.'}/></td></tr>}</tbody></table></div><TablePagination total={results.length} page={page} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={setPageSize}/></section><div className="inline-help"><b>Supplier records</b><span>Supplier history and linked GRNs should remain available for audit after deactivation.</span><button>Purchase history <span><UiIcon name="file" size={14}/></span></button></div></>; }

function AuditLogs({rows,error,loading,search,setSearch}:{rows:any[];error:string;loading:boolean;search:string;setSearch:(s:string)=>void}) { const results=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));const [page,setPage]=useState(1);const [pageSize,setPageSize]=useState(5);const pageRows=results.slice((page-1)*pageSize,page*pageSize);useEffect(()=>setPage(1),[search]);return <><section className="panel audit-filters"><div className="search-field"><span><UiIcon name="search" size={16}/></span><input id="page-search" placeholder="Search user, event or reference" value={search} onChange={e=>setSearch(e.target.value)} /></div><input aria-label="From date" type="date" /><input aria-label="To date" type="date" /><select><option>All modules</option><option>Users</option><option>Inventory</option><option>Payments</option></select><select><option>All outcomes</option><option>Success</option><option>Failure</option><option>Review required</option></select><Button disabled={!results.length} onClick={()=>downloadCsv('audit-logs.csv',results)}><UiIcon name="download" size={15}/> Export CSV</Button></section>{error&&<div className="inline-error">{error}</div>}<section className="panel table-panel"><div className="table-wrap"><table><thead><tr><th>S/N</th><th>TIMESTAMP</th><th>USER</th><th>EVENT</th><th>MODULE</th><th>RECORD REFERENCE</th><th>OUTCOME</th><th>DETAILS</th></tr></thead><tbody>{pageRows.map((r,i)=><tr key={r.id}><td>{(page-1)*pageSize+i+1}</td><td>{new Date(r.occurred_at).toLocaleString()}</td><td>{r.actor_name||'System'}</td><td>{r.action}</td><td>{r.module}</td><td>{r.reference_no||r.entity_id||'—'}</td><td>{r.outcome}</td><td><button className="row-action" disabled title="Details view is not implemented yet">Details</button></td></tr>)}{!results.length&&<tr><td colSpan={8}><Empty title={loading?'Loading audit events':error?'Audit service unavailable':'No audit events found'} note={error||'Events generated by successful administrative actions appear here.'}/></td></tr>}</tbody></table></div><TablePagination total={results.length} page={page} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={setPageSize}/></section><div className="security-callout"><span><UiIcon name="file" size={14}/></span><div><b>Audit history is protected</b><p>Normal application users must not be able to edit or delete audit records. Access to record details and exports is permission controlled.</p></div></div></>; }

function SystemHealth({rows,error,loading}:{rows:any[];error:string;loading:boolean}) { const [page,setPage]=useState(1);const [pageSize,setPageSize]=useState(5);const pageRows=rows.slice((page-1)*pageSize,page*pageSize);useEffect(()=>setPage(1),[rows.length]);const cards=[['Application','—','Availability status'],['Database',error?'Unavailable':'Connected','MySQL database connection'],['Background jobs','—','Queue and task status'],['Backups',rows.filter(r=>r.component==='backup'&&r.status==='open').length?'Attention':'—','Most recent backup status'],['Storage','—','Usage and capacity'],['Failed operations',String(rows.filter(r=>r.severity==='error'||r.severity==='critical').length),'Open error events']]; return <><div className="health-banner"><div className="health-orb"><UiIcon name="shield" size={20}/></div><div><span className="eyebrow">SYSTEM STATUS</span><h2>{error?'Health data could not be loaded':'System health events and database status'}</h2><p>{error||'Database connectivity is verified by successful administration data requests.'}</p></div><span className="soft-pill soft-amber">{error?'Unavailable':loading?'Loading':'Monitoring'}</span></div><div className="health-grid">{cards.map(([a,b,c])=><article className="health-card" key={a}><div className="health-card-icon"><UiIcon name="chart" size={18}/></div><span>{a}</span><b>{b}</b><small>{c}</small></article>)}</div><section className="panel table-panel"><CardTitle title="Recent system events" extra={<select className="mini-select"><option>All components</option></select>} /><div className="table-wrap"><table><thead><tr><th>S/N</th><th>COMPONENT</th><th>SEVERITY</th><th>EVENT</th><th>FIRST SEEN</th><th>STATUS</th></tr></thead><tbody>{pageRows.map((r,i)=><tr key={r.id}><td>{(page-1)*pageSize+i+1}</td><td>{r.component}</td><td>{r.severity}</td><td>{r.message}</td><td>{new Date(r.first_seen_at).toLocaleString()}</td><td>{r.status}</td></tr>)}{!rows.length&&<tr><td colSpan={6}><Empty title={loading?'Loading health events':error?'Health data unavailable':'No health events'} note={error||'No open health events are recorded.'}/></td></tr>}</tbody></table></div><TablePagination total={rows.length} page={page} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={setPageSize}/></section><div className="security-callout"><span><UiIcon name="file" size={14}/></span><div><b>Secrets are never displayed here</b><p>Health views must not expose passwords, access tokens, database credentials, or connection strings.</p></div></div></>; }

function Notifications({rows,error,onRead}:{rows:any[];error:string;onRead:(id:number)=>void}) { return <><div className="notification-filters"><span className="filter-active">All notifications</span><span>Unread: {rows.filter(r=>!r.read_at).length}</span></div>{error&&<div className="inline-error">{error}</div>}<section className="panel notification-list">{rows.length?rows.map(r=><article className="notification-item" key={r.id}><span className={`notification-severity severity-${r.severity}`}/><div><strong>{r.title}</strong><p>{r.message}</p><small>{r.category} — {new Date(r.created_at).toLocaleString()}</small></div>{!r.read_at&&<button className="row-action" onClick={()=>onRead(r.id)}>Mark read</button>}</article>):<Empty title="You're all caught up" note="Notifications are loaded from your account inbox in hospitalguru." />}</section></>; }
function Reports({notify}:{notify:(s:string)=>void}) { const [busy,setBusy]=useState('');const reports=[['User access report','Account status, roles and location assignments','users','user-access.csv'],['System activity report','Audited user actions and transaction activity','audit','system-activity.csv'],['Inventory configuration','Batch balances, reorder levels, and expiry state','inventory','inventory-configuration.csv'],['Backup history','Recorded backup runs and service outcomes','backup_runs','backup-history.csv']];async function exportReport(title:string,resource:string,file:string){setBusy(title);try{const response=await fetch(`/api/admin?resource=${resource}`);const body=await response.json();if(!response.ok)throw new Error(body.error||'Report data could not be loaded.');const rows=Array.isArray(body.data)?body.data:[];if(!rows.length){notify('No records are available for this report yet.');return}downloadCsv(file,rows);notify(`${title} exported (${rows.length} records).`)}catch(error){notify(error instanceof Error?error.message:'Report export failed.')}finally{setBusy('')}}return <><div className="report-grid">{reports.map(([title,description,resource,file])=><article className="report-card" key={title}><div className="report-icon"><UiIcon name="file" size={18}/></div><h2>{title}</h2><p>{description}</p><button disabled={!!busy} onClick={()=>exportReport(title,resource,file)}>{busy===title?'Preparing—':'Export report'} <span><UiIcon name="file" size={14}/></span></button></article>)}</div><div className="connection-note"><span className="connection-icon">i</span><div><strong>Reports are exported from authorized hospitalguru records.</strong><span>Each report uses the current account—s existing permissions and data scope.</span></div></div></>; }
function Profile() { return <div className="profile-grid"><section className="panel profile-card"><div className="profile-cover" /><div className="profile-avatar avatar">SA</div><h2>Super Administrator</h2><p>Administration account</p><span className="status-pill status-active"><i />Active</span><div className="profile-data"><Field label="Username" placeholder="Loaded from account service" /><Field label="Email" placeholder="Loaded from account service" /><Field label="Role" value="Super Administrator" /><Field label="Assigned locations" value="All authorized locations" /></div></section><section className="panel security-card"><CardTitle title="Security" /><div className="security-option"><div><b>Change password</b><span>Update your account password.</span></div><Button disabled>Change password</Button></div><div className="security-option"><div><b>Active sessions</b><span>Review and revoke signed-in devices.</span></div><Button disabled>Manage sessions</Button></div><div className="security-option"><div><b>Recent sign-in activity</b><span>Review successful and failed account access.</span></div><Button disabled>View activity</Button></div></section></div>; }

async function saveSettings(tab:string,notify:(s:string)=>void){const input=Array.from(document.querySelectorAll<HTMLInputElement>('.settings-content .form-grid .field input')).map(x=>x.value.trim());const keys:Record<string,string[]>={General:['hospital_name','contact_email','phone','address','timezone','default_language'],Inventory:['expiry_warning_days','low_stock_threshold','negative_stock_policy','valuation_method'],Sales:['currency','payment_methods','receipt_format','discount_approval'],Security:['session_timeout','password_policy','mfa_policy','login_rate_limits'],Documents:['grn_prefix','transfer_prefix','return_prefix','invoice_prefix','receipt_prefix']};const selected=keys[tab]||[];const settings=Object.fromEntries(selected.slice(0,input.length).map((k,i)=>[k,input[i]]));if(settings.currency)settings.currency=String(settings.currency).slice(0,3);if(settings.expiry_warning_days)settings.expiry_warning_days=String(settings.expiry_warning_days).replace(/\D/g,'');if(settings.low_stock_threshold)settings.low_stock_threshold=String(settings.low_stock_threshold).replace(/\D/g,'');try{const r=await fetch('/api/admin',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({resource:'settings',settings})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Settings could not be saved.');notify(`${d.updated} settings saved and audited.`)}catch(e){notify(e instanceof Error?e.message:'Settings could not be saved.')}}
async function saveInventorySettings(notify:(s:string)=>void){const input=Array.from(document.querySelectorAll<HTMLInputElement>('.settings-panel .form-grid .field input')).map(x=>x.value.trim());const settings={low_stock_threshold:input[0]?.replace(/\D/g,''),expiry_warning_days:input[1]?.replace(/\D/g,''),negative_stock_policy:input[2],valuation_method:input[3]};try{const r=await fetch('/api/admin',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({resource:'settings',settings})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Settings could not be saved.');notify(`${d.updated} inventory settings saved.`)}catch(e){notify(e instanceof Error?e.message:'Settings could not be saved.')}}
function Field({label,value,placeholder}:{label:string;value?:string;placeholder?:string}) { return <div className="field"><label>{label}</label><input defaultValue={value} placeholder={placeholder} /></div>; }
function Modal({title,close,notify,onSaved,locationRows}:{title:string;close:()=>void;notify:(s:string)=>void;onSaved:()=>void;locationRows:any[]}) { const isUser=title==='Create user'; const isDrug=title==='Add drug'; const isSupplier=title==='Add supplier'; const fields=isUser?['Full name','Username','Email','Staff ID','Role','Assigned locations','Account status','Temporary password']:isDrug?['Drug code / SKU','Generic name','Brand name','Barcode','Category','Strength','Dosage form','Base unit']:isSupplier?['Supplier name','Supplier code','Contact person','Phone','Email','Address','Registration details']:['Location name','Location code','Location type','Address','Phone']; const [saving,setSaving]=useState(false);const [error,setError]=useState('');async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setSaving(true);setError('');const form=new FormData(e.currentTarget);const get=(label:string)=>String(form.get(fieldName(label))||'').trim();const getAll=(label:string)=>form.getAll(fieldName(label)).map(x=>String(x));const payload:any={resource:isUser?'users':isDrug?'drugs':isSupplier?'suppliers':'locations'};if(isUser){const roleLabel=get('Role');payload.name=get('Full name');payload.username=get('Username');payload.email=get('Email');payload.staff_id=get('Staff ID');payload.role_key=({ 'Super Administrator':'super_administrator','CMD / Authorized Executive':'cmd_executive','Head Pharmacist':'head_pharmacist','DRF Store Keeper':'drf_store_keeper','Pharmacy Dispenser':'pharmacy_dispenser','Pharmacy Supervisor':'pharmacy_supervisor','Cashier':'cashier','Procurement Officer':'procurement_officer','Internal Auditor':'internal_auditor','System Administrator':'system_administrator'} as Record<string,string>)[roleLabel];payload.location_ids=getAll('Assigned locations');payload.status=get('Account status').toLowerCase()||'active';payload.password=get('Temporary password')}else if(isDrug){payload.sku=get('Drug code / SKU');payload.generic_name=get('Generic name');payload.brand_name=get('Brand name');payload.barcode=get('Barcode');payload.category=get('Category');payload.strength=get('Strength');payload.dosage_form=get('Dosage form');payload.base_unit=get('Base unit')||'unit'}else if(isSupplier){payload.name=get('Supplier name');payload.code=get('Supplier code');payload.contact_person=get('Contact person');payload.phone=get('Phone');payload.email=get('Email');payload.address=get('Address');payload.registration_no=get('Registration details')}else{payload.name=get('Location name');payload.code=get('Location code');payload.type=({'Central Store':'central_store','Pharmacy':'pharmacy','Other':'other'} as Record<string,string>)[get('Location type')];payload.address=get('Address');payload.phone=get('Phone')}try{const res=await fetch('/api/admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await res.json();if(!res.ok)throw new Error(d.error||'Unable to save this record.');notify(`${isUser?'User':isDrug?'Medicine':isSupplier?'Supplier':'Location'} saved.`);onSaved();close()}catch(err){setError(err instanceof Error?err.message:'Save failed.')}finally{setSaving(false)}}return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-header"><div><span className="eyebrow">ADMINISTRATION</span><h2 id="modal-title">{title}</h2></div><button onClick={close} className="modal-close" aria-label="Close">—</button></div><div className="modal-note"><span>i</span><p>{title==='Location details'?'Location details are read-only.':isUser?'User creation is restricted to the Super Administrator role and is recorded in the audit log.':'New records are saved to hospitalguru and recorded in the audit log.'}</p></div>{error&&<div className="inline-error">{error}</div>}<form onSubmit={submit}><div className="modal-fields">{fields.map(f=><div className={`field ${f==='Address'?'full':''}`} key={f}><label htmlFor={`modal-${fieldName(f)}`}>{f}{['Full name','Username','Role','Generic name','Supplier name','Location name','Location code'].includes(f)&&<i> Required</i>}</label>{f==='Role'?<select id={`modal-${fieldName(f)}`} name={fieldName(f)} defaultValue="" required><option value="" disabled>Select role</option>{roleNames.map(r=><option key={r}>{r}</option>)}</select>:f==='Assigned locations'||f==='Location type'||f==='Account status'?<select id={`modal-${fieldName(f)}`} name={fieldName(f)} multiple={f==='Assigned locations'} defaultValue={f==='Account status'?'Active':f==='Assigned locations'?[]:''} required={f!=='Account status'&&f!=='Assigned locations'}><option value="" disabled>Select {f.toLowerCase()}</option>{f==='Assigned locations'?locationRows.map(l=><option key={l.id} value={l.id}>{l.name}</option>):(f==='Location type'?['Central Store','Pharmacy','Other']:['Active','Suspended','Pending']).map(o=><option key={o}>{o}</option>)}</select>:<input id={`modal-${fieldName(f)}`} name={fieldName(f)} type={f.toLowerCase().includes('password')?'password':f==='Email'?'email':'text'} minLength={f==='Temporary password'?10:undefined} required={['Full name','Username','Temporary password','Drug code / SKU','Generic name','Supplier name','Location name','Location code'].includes(f)} placeholder={f==='Temporary password'?'At least 10 characters':`Enter ${f.toLowerCase()}`} />}</div>)}</div><div className="modal-footer"><Button onClick={close}>Cancel</Button><button className="button button-primary" disabled={saving||title==='Location details'}>{saving?'Saving—':`Save ${isUser?'user':isDrug?'drug':isSupplier?'supplier':'location'}`}</button></div></form></section></div>; }
function fieldName(s:string){return s.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')}
